window.GuanwuCommunity=(()=>{
 let me=null,activeController=null,profileReturn=null,composeDraft=null,feedFilter={city:'',topic:'',mine:false},nextCursor=null,loadedPosts=[];
 const topics=['观察','问题','行程','分享'];
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function api(path,options={}){const r=await fetch('/api/community'+path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers},cache:'no-store'});let data;try{data=await r.json()}catch{throw Error('交流服务暂时不可用，请稍后重试。')}if(!r.ok){const error=new Error(data.error||'操作没有完成，请稍后重试。');error.status=r.status;throw error}return data}
 const date=s=>{const d=new Date(s);return Number.isFinite(d.getTime())?d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):''};
 function authPath(out=false){const target=(new URLSearchParams(location.search).get('mode')==='mini'?'/mini.html':'/')+location.hash;return (out?'/signout-with-chatgpt':'/signin-with-chatgpt')+'?return_to='+encodeURIComponent(target)}
 const postMuseum=p=>p.museumId?museums.find(m=>m.id===p.museumId):null;
 function page(){return `${title('LOOKING TOGETHER','把一个发现，交给另一个人','分享看展时的好奇、路线与观察。在这里，遇见和你一起认真看的人。')}<div class="community-welcome"><div><span>同行交流</span><p>这里的内容来自访客分享，与馆方资料及 AI 讲解分别呈现。</p></div><div id="community-account"><span>正在连接交流区…</span></div><button class="solid-btn" data-community-compose>＋ 写一篇分享</button></div><div class="community-filters"><label><span class="sr-only">按城市筛选帖子</span><select id="community-city"><option value="">全部城市</option>${[...new Set(museums.map(m=>m.city))].map(c=>`<option ${feedFilter.city===c?'selected':''} value="${c}">${c}</option>`).join('')}</select></label><div>${['全部',...topics].map(t=>`<button data-community-topic="${t==='全部'?'':t}" class="${feedFilter.topic===(t==='全部'?'':t)?'active':''}">${t}</button>`).join('')}</div><button class="text-link" data-community-refresh aria-label="刷新交流区">↻ 新分享</button><button class="community-my ${feedFilter.mine?'active':''}" data-community-mine>我的分享</button></div><div class="community-feed" id="community-feed" aria-live="polite"><div class="community-loading">正在读同行的手记…</div></div><button class="browse-more" id="community-more" data-community-more hidden>再看一些分享 ↓</button>`}
 function teaser(){return `<section class="community-invite"><div><div class="eyebrow">A COMMUNITY OF CURIOSITY</div><h2>你的一个发现，<br>也许是别人的下一站。</h2><p>把观看手记、城市路线与心里的问题，分享给同样好奇的人。</p></div><a class="solid-btn" href="#community">去同行交流看看 ↗</a></section>`}
 function card(p){const m=postMuseum(p);return `<article class="community-post-card"><div class="community-post-meta"><span class="community-avatar">${escape(Array.from(p.author.nickname||'观')[0])}</span><span>${escape(p.author.nickname)}</span><small>${date(p.createdAt)}</small><b>${escape(p.topic)}</b>${p.status==='hidden'?'<small>已隐藏 · 仅自己可见</small>':''}</div><h2><a href="#post/${p.id}">${escape(p.title)}</a></h2><p class="community-excerpt">${escape(p.body.slice(0,180))}${p.body.length>180?'…':''}</p>${p.route?`<a class="community-route-preview" href="#post/${p.id}"><span>⌖</span><div><strong>${escape(p.route.name)}</strong><small>${p.route.ids.map(id=>escape(museums.find(m=>m.id===id)?.name||'')).join(' → ')}</small></div><b>↗</b></a>`:''}<div class="community-card-foot"><span>${m?escape(m.name):p.city?escape(p.city):'展览之外，也有故事'}</span><a href="#post/${p.id}">♡ ${p.likeCount} <span>·</span> ${p.commentCount} 条回复 →</a></div></article>`}
 function account(){const el=document.getElementById('community-account');if(!el)return;if(!me?.authenticated)el.innerHTML=`<a class="outline-btn" href="${escape(authPath())}" target="_top">登录，加入交流 ↗</a>`;else el.innerHTML=`<button class="text-link" data-community-profile>${escape(me.nickname||'设置公开昵称')} ↗</button>${me.moderator?'<a class="text-link" href="#moderation">管理举报 ↗</a>':''}<a class="text-link" href="${escape(authPath(true))}" target="_top">退出</a>`}
 function emptyFeed(){return `<div class="community-empty"><span>✧</span><h2>${feedFilter.mine?'这里会留下你的分享。':'还没有人写下这一页。'}</h2><p>${feedFilter.city?'换座城市看看，或留下你的第一条观察。':'一件让你驻足的文物，一段值得留白的路线，都可以成为交流的开始。'}</p><button class="outline-btn" data-community-compose>写下我的发现 →</button></div>`}
 async function fetchFeed(append=false){if(append&&!nextCursor)return;const target=document.getElementById('community-feed');if(!target)return;const controller=new AbortController();activeController?.abort();activeController=controller;const params=new URLSearchParams();if(feedFilter.city)params.set('city',feedFilter.city);if(feedFilter.topic)params.set('topic',feedFilter.topic);if(feedFilter.mine)params.set('mine','1');if(append&&nextCursor)params.set('before',nextCursor);try{const data=await api('/posts?'+params,{signal:controller.signal});loadedPosts=append?[...loadedPosts,...data.posts]:data.posts;nextCursor=data.next;target.innerHTML=loadedPosts.length?loadedPosts.map(card).join(''):emptyFeed();document.getElementById('community-more').hidden=!nextCursor}catch(error){if(error.name==='AbortError')return;target.innerHTML=`<div class="community-empty"><h2>这页手记暂未打开。</h2><p>${escape(error.message)}</p><button class="outline-btn" data-community-retry>再试一次</button></div>`}}
 function signInPanel(){dialog(`<div class="eyebrow">LOOKING TOGETHER</div><h2 id="modal-title">登录，留下你的声音。</h2><p>游客可以阅读。登录后，可用自己选择的公开昵称分享、回复和点赞。</p><a class="solid-btn community-signin" href="${escape(authPath())}" target="_top">使用 ChatGPT 登录 ↗</a><p class="tiny-note">这一步使用当前站点的登录服务；不会公开你的邮箱。</p>`)}
 async function ensureUser(next){try{me=await api('/me');account()}catch(error){toast(error.message);return false}if(!me.authenticated){signInPanel();return false}if(!me.nickname){profileReturn=next;profileForm();return false}return true}
 function profileForm(){dialog(`<div class="eyebrow">YOUR PUBLIC NAME</div><h2 id="modal-title">选一个交流时的名字。</h2><p>昵称和你发布的内容会公开显示，邮箱不会公开。</p><form id="community-profile-form"><label class="community-field">公开昵称<input id="community-nickname" value="${escape(me?.nickname||'')}" minlength="2" maxlength="20" required placeholder="例如：慢慢看展的人"></label><button class="solid-btn" type="submit">保存公开昵称 →</button><p class="community-form-error" role="alert"></p></form>`);document.getElementById('community-nickname').focus()}
 function compose(seed={}){composeDraft={...(composeDraft||{}),...seed};openCompose()}
 async function openCompose(){if(!await ensureUser(openCompose))return;const d=composeDraft||{},selectedMuseum=museums.find(m=>m.id===d.museumId);dialog(`<div class="eyebrow">A NOTE FOR FELLOW TRAVELERS</div><h2 id="modal-title">把发现，写给同行的人。</h2><form id="community-post-form"><label class="community-field">标题<input id="community-post-title" maxlength="80" minlength="2" value="${escape(d.title||'')}" placeholder="哪件文物，让你多看了一会儿？" required></label><div class="community-compose-options"><label class="community-field">话题<select id="community-post-topic">${topics.map(t=>`<option ${d.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="community-field">城市<select id="community-post-city"><option value="">不限城市</option>${[...new Set(museums.map(m=>m.city))].map(c=>`<option value="${c}" ${(d.city||selectedMuseum?.city)===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label class="community-field">关联博物馆（可选）<select id="community-post-museum"><option value="">暂不关联</option>${museums.map(m=>`<option value="${m.id}" ${m.id===d.museumId?'selected':''}>${m.city} · ${escape(m.name)}</option>`).join('')}</select></label><label class="community-field">你的观察或问题<textarea id="community-post-body" maxlength="3000" minlength="5" rows="6" placeholder="说说你看到的，也可以问问大家会怎样看。" required>${escape(d.body||'')}</textarea></label>${d.route?`<div class="community-attached-route"><strong>附上这份路线：${escape(d.route.name)}</strong><p>${d.route.ids.map(id=>escape(museums.find(m=>m.id===id)?.name||'')).join(' → ')}</p><small>仅分享场馆顺序与出行方式，不公开私人日期或开始时间。</small><button type="button" class="text-link" data-community-detach>不附路线 ×</button></div>`:''}<p class="tiny-note">以 ${escape(me.nickname)} 发布到公开交流区。馆藏事实请尽量附来源，不要把个人推测写成馆方结论。</p><button type="submit" class="solid-btn">发布这篇分享 →</button><p class="community-form-error" role="alert"></p></form>`)}
 function postPage(id){return `<div class="detail-breadcrumb"><a href="#community">同行交流</a><span>/</span>一篇观看手记</div><div id="community-post-detail" data-post-id="${escape(id)}"><div class="community-loading">正在读这篇分享…</div></div>`}
 async function loadPost(id){const container=document.getElementById('community-post-detail');if(!container)return;try{const data=await api('/posts/'+encodeURIComponent(id)),p=data.post,m=postMuseum(p);container.innerHTML=`<article class="community-detail"><div class="community-post-meta"><span class="community-avatar">${escape(Array.from(p.author.nickname)[0])}</span><span>${escape(p.author.nickname)}</span><small>${date(p.createdAt)}</small><b>${escape(p.topic)}</b></div><h1>${escape(p.title)}</h1><div class="community-detail-body">${escape(p.body)}</div>${p.route?`<div class="community-full-route"><div class="eyebrow">A ROUTE SHARED WITH YOU</div><h2>${escape(p.route.name)}</h2><ol>${p.route.ids.map(id=>`<li><a href="#museum/${id}">${escape(museums.find(m=>m.id===id)?.name||'场馆')} ↗</a></li>`).join('')}</ol><button class="outline-btn" data-community-import-route="${p.id}">复制为我的路线，继续修改 →</button><p class="tiny-note">这是访客分享的参观顺序。馆区、开放、预约与交通请在出发前核对。</p></div>`:''}<div class="community-detail-tags">${m?`<a href="#museum/${m.id}">${m.city} · ${escape(m.name)} ↗</a>`:escape(p.city||'观看手记')}${p.status==='hidden'?'<span>这篇分享已被隐藏</span>':''}</div><div class="community-post-actions"><button class="outline-btn ${data.liked?'liked':''}" data-community-like="${id}" data-liked="${data.liked}">${data.liked?'♥ 已赞':'♡ 点赞'} · ${p.likeCount}</button>${p.author.isSelf?`<button class="text-link" data-community-delete-post="${id}">删除我的分享</button>`:`<button class="text-link" data-community-report="${id}">举报</button>`}${me?.moderator?`<button class="text-link" data-community-moderate="${id}" data-status="${p.status==='hidden'?'published':'hidden'}">${p.status==='hidden'?'恢复公开':'隐藏这篇分享'}</button>`:''}</div></article><section class="community-replies"><div class="section-head"><div class="section-title"><h2>一起多看一点</h2><span>${p.commentCount} REPLIES</span></div></div>${data.comments.length?data.comments.map(c=>`<article class="community-comment"><div><strong>${escape(c.nickname)}</strong><small>${date(c.createdAt)}</small>${c.isSelf||me?.moderator?`<button class="text-link" data-community-delete-comment="${c.id}" data-post="${id}">删除</button>`:''}</div><p>${escape(c.body)}</p></article>`).join(''):'<div class="community-no-replies">还没有回复。留下一句自己的观察，让讨论开始。</div>'}${data.commentsLimited?'<p class="tiny-note">当前展示前100条回复。</p>':''}${me?.authenticated?`<form class="community-reply-form" id="community-reply-form" data-post="${id}"><label for="community-reply">你的回复</label><textarea id="community-reply" maxlength="1000" rows="3" placeholder="从一个细节，接住另一个人的好奇……" required></textarea><button class="solid-btn" type="submit">回复这篇分享 →</button><p class="community-form-error" role="alert"></p></form>`:`<div class="community-no-replies"><p>登录后，写下你的回复。</p><button class="outline-btn" data-community-login>登录参与交流 ↗</button></div>`}</section>`;container._route=p.route}catch(error){container.innerHTML=`<div class="community-empty"><h2>暂时看不到这篇分享。</h2><p>${escape(error.message)}</p><a class="text-link" href="#community">回到同行交流 →</a></div>`}}
 function reportForm(id){dialog(`<h2 id="modal-title">告诉我们需要留意什么。</h2><p>举报会交给站点管理者查看。</p><form id="community-report-form" data-post="${id}"><label class="community-field">原因<textarea id="community-report-reason" minlength="2" maxlength="200" rows="3" required placeholder="例如：广告、冒用身份或不当内容"></textarea></label><button class="solid-btn" type="submit">提交举报</button><p class="community-form-error" role="alert"></p></form>`)}
 function moderationPage(){return `${title('COMMUNITY CARE','让交流，保持认真与友善','查看访客举报，再决定是否隐藏相关分享。')}<div id="community-moderation"><p class="community-loading">正在读取待处理举报…</p></div>`}
 async function loadModeration(){const el=document.getElementById('community-moderation');if(!el)return;try{const data=await api('/reports');el.innerHTML=data.reports.length?data.reports.map(r=>`<article class="moderation-report"><small>${date(r.created_at)} · ${escape(r.nickname||'同行用户')}</small><h2><a href="#post/${r.post_id}">${escape(r.title)} ↗</a></h2><p>${escape(r.reason)}</p><button class="outline-btn" data-community-moderate="${r.post_id}" data-status="hidden">隐藏分享并处理举报</button><button class="text-link" data-community-moderate="${r.post_id}" data-status="published">保留分享，标记已查看</button></article>`).join(''):'<div class="community-empty"><h2>暂无待处理的举报。</h2><p>这里会保留需要你查看的交流内容。</p></div>'}catch(error){el.innerHTML=`<div class="community-empty"><p>${escape(error.message)}</p><a href="#community">回到交流区 →</a></div>`}}
 async function mount(route){activeController?.abort();if(!['community','post','moderation'].includes(route.split('/')[0]))return;const current=route;try{me=await api('/me')}catch(error){me=null}if((location.hash.slice(1)||'discover')!==current)return;if(route==='community'){account();fetchFeed()}else if(route.startsWith('post/'))loadPost(route.split('/')[1]);else loadModeration()}
 async function busyForm(form,action){const button=form.querySelector('button[type="submit"]'),error=form.querySelector('.community-form-error');button.disabled=true;error.textContent='';try{await action()}catch(e){error.textContent=e.message}finally{button.disabled=false}}
 document.addEventListener('submit',e=>{const form=e.target;if(!form.id.startsWith('community-'))return;e.preventDefault();busyForm(form,async()=>{
  if(form.id==='community-profile-form'){const data=await api('/profile',{method:'PUT',body:JSON.stringify({nickname:document.getElementById('community-nickname').value})});me.nickname=data.nickname;document.getElementById('modal').close();account();toast('公开昵称已保存');const next=profileReturn;profileReturn=null;if(next)next()}
  if(form.id==='community-post-form'){const d={title:document.getElementById('community-post-title').value,body:document.getElementById('community-post-body').value,topic:document.getElementById('community-post-topic').value,city:document.getElementById('community-post-city').value||null,museumId:document.getElementById('community-post-museum').value||null,route:composeDraft?.route||null};const data=await api('/posts',{method:'POST',body:JSON.stringify(d)});composeDraft=null;document.getElementById('modal').close();location.hash='post/'+data.id;toast('分享已发布，其他访客现在可以阅读和回复。')}
  if(form.id==='community-reply-form'){if(!await ensureUser(()=>document.getElementById('community-reply').focus()))return;await api('/posts/'+form.dataset.post+'/comments',{method:'POST',body:JSON.stringify({body:document.getElementById('community-reply').value})});await loadPost(form.dataset.post);toast('回复已留下')}
  if(form.id==='community-report-form'){await api('/posts/'+form.dataset.post+'/report',{method:'POST',body:JSON.stringify({reason:document.getElementById('community-report-reason').value})});document.getElementById('modal').close();toast('举报已提交给站点管理者')}
 })});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
  if(b.hasAttribute('data-community-login'))signInPanel();if(b.hasAttribute('data-community-compose'))compose();if(b.hasAttribute('data-community-profile'))profileForm();
  if(b.dataset.communityTopic!==undefined){feedFilter.topic=b.dataset.communityTopic;render(false)}
  if(b.hasAttribute('data-community-mine')){if(!me?.authenticated){signInPanel();return}feedFilter.mine=!feedFilter.mine;render(false)}
  if(b.hasAttribute('data-community-more'))fetchFeed(true);if(b.hasAttribute('data-community-retry')||b.hasAttribute('data-community-refresh'))fetchFeed();
  if(b.hasAttribute('data-community-detach')){composeDraft={...(composeDraft||{}),title:document.getElementById('community-post-title').value,body:document.getElementById('community-post-body').value,topic:document.getElementById('community-post-topic').value,city:document.getElementById('community-post-city').value,museumId:document.getElementById('community-post-museum').value,route:null};openCompose()}
  if(b.dataset.communityLike){if(!await ensureUser())return;await api('/posts/'+b.dataset.communityLike+'/like',{method:b.dataset.liked==='true'?'DELETE':'PUT'});loadPost(b.dataset.communityLike)}
  if(b.dataset.communityReport){if(!await ensureUser())return;reportForm(b.dataset.communityReport)}
  if(b.dataset.communityDeletePost)dialog(`<h2 id="modal-title">删除自己的这篇分享？</h2><p>删除后，这篇分享及其回复会一并移除。</p><button class="solid-btn" data-community-confirm-delete="${b.dataset.communityDeletePost}">确认删除分享</button>`);
  if(b.dataset.communityConfirmDelete){await api('/posts/'+b.dataset.communityConfirmDelete,{method:'DELETE'});document.getElementById('modal').close();location.hash='community';toast('分享已删除')}
  if(b.dataset.communityDeleteComment){dialog(`<h2 id="modal-title">删除这条回复？</h2><button class="solid-btn" data-community-confirm-comment="${b.dataset.communityDeleteComment}" data-post="${b.dataset.post}">确认删除回复</button>`)}
  if(b.dataset.communityConfirmComment){await api('/comments/'+b.dataset.communityConfirmComment,{method:'DELETE'});document.getElementById('modal').close();loadPost(b.dataset.post)}
  if(b.dataset.communityModerate){await api('/posts/'+b.dataset.communityModerate+'/moderate',{method:'PUT',body:JSON.stringify({status:b.dataset.status})});if(location.hash==='#moderation')loadModeration();else loadPost(b.dataset.communityModerate);toast('处理已保存')}
  if(b.dataset.communityImportRoute){const r=document.getElementById('community-post-detail')._route;GuanwuRoutePlanner.importRoute(r)}
 }catch(error){toast(error.message)}});
 document.addEventListener('change',e=>{if(e.target.id==='community-city'){feedFilter.city=e.target.value;render(false)}if(e.target.id==='community-post-museum'){const m=museums.find(m=>m.id===e.target.value);if(m)document.getElementById('community-post-city').value=m.city}});
 return {page,postPage,moderationPage,mount,compose,teaser};
})();
